# BEGIN_C_BLOCK block_id=pc-unnecessary-scan-or-while-ex1 kind=example title="Take item nearby without unnecessary scan or while"
{
  "plan": [
    { "type": "move", "target": "Apple" },
    { "type": "take", "target": "Apple" }
  ]
}
# END_C_BLOCK block_id=pc-unnecessary-scan-or-while-ex1

# BEGIN_C_BLOCK block_id=pc-missing-or-incomplete-goal-ex1 kind=example title="Eat berries to reduce hunger"
{
  "plan": [
    { "type": "scan", "target": "Berries", "out": "berries_loc" },
    { "type": "while", "condition": { "type": "notnear", "target": "$berries_loc" }, "body": [
      { "type": "move", "target": "$berries_loc" }
    ]},
    { "type": "take", "target": "$berries_loc" },
    { "type": "use", "target": "$berries_loc", "reason": "reduce hunger" }
  ]
}
# END_C_BLOCK block_id=pc-missing-or-incomplete-goal-ex1

# BEGIN_C_BLOCK block_id=pc-extra-unneeded-step-ex1 kind=example title="Stop after delivering item; no extra steps"
{
  "plan": [
    { "type": "scan", "target": "Basket", "out": "basket_loc" },
    { "type": "while", "condition": { "type": "notnear", "target": "$basket_loc" }, "body": [
      { "type": "move", "target": "$basket_loc" }
    ]},
    { "type": "place", "target": "Apple" }
  ]
}
# END_C_BLOCK block_id=pc-extra-unneeded-step-ex1
